{
 "research_concepts": [
  "Lineup roles (organizer, shaper, terminal)",
  "Lineup composition effects",
  "Talent as a confounder",
  "Within-team analysis",
  "Separability of role effects from talent"
 ],
 "methodological_questions": [
  "How to define and identify organizer, shaper, terminal roles from play-by-play data?",
  "How to control for player talent in lineup studies?",
  "How to establish separability of role effects from talent?",
  "How to measure within-team variation of lineup coverage?"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-009",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph."
  },
  {
   "id": "FAM:SF-APPA-005",
   "status_as_recorded": "untestable",
   "finding": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "Play-type actions have decaying cross-possession memory (lag-1 effect >= lag-2; not just score margin or team quality). Result: FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Embiid 23-24 cascades with Reed sim 0.94."
  },
  {
   "id": "FAM:SF-PAP-096",
   "status_as_recorded": "artifact",
   "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20"
  },
  {
   "id": "FAM:SF-APPS-073",
   "status_as_recorded": "artifact",
   "finding": "Global horizons: DRIVE/SPOT_UP/TRANSITION=5; others 0 (PNR/CUT/POST_UP/PUTBACK). SPOT_UP lag-1 lift +0.027 ctrl_p=0.0000. Within-team: all horizons 0 except SPOT_UP horizon(all)=1; PNR lag-1 within_team_lift=-0.0218."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-CHT-009",
   "what_failed": "Analyzing superstar suppression by lineup without placebo or matching controls.",
   "why": "No placebo or matching; later sequence work treated similar star-chain gaps as artifacts. (RISK:PLACEBO_DEPENDENCE)"
  },
  {
   "id": "FAM:SF-APPA-005",
   "what_failed": "Inferring defensive scheme changes from play-by-play data.",
   "why": "Inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise. (LIM:label_or_classification_error, RISK:LABEL_ERROR)"
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Detecting persistent impact score lag effects globally.",
   "why": "Flat non-decaying lifts collapse under within-team baseline; team-quality confound. (LIM:confounding, RISK:CONFOUNDING)"
  },
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using player similarity to separate absorption from cascade when a player sits.",
   "why": "Similarity does not separate absorption from cascade; almost always findable. (LIM:label_or_classification_error, RISK:LABEL_ERROR)"
  },
  {
   "id": "FAM:SF-PAP-096",
   "what_failed": "Using a play-type classifier where the 'assisted' flag was only present on makes.",
   "why": "assisted flag on makes only produced SPOT_UP 2.83 PPP (C_artifact)"
  },
  {
   "id": "FAM:SF-APPS-073",
   "what_failed": "Detecting persistent impact score lag effects globally.",
   "why": "Flat non-decaying global lifts disappear after team-season demeaning; remaining within-team memory is essentially none except SPOT_UP lag-1. (C_artifact)"
  }
 ],
 "evidence_establishes": [
  "The necessity of robust controls, especially within-team demeaning, to avoid confounding by team quality or other global factors when analyzing play-type effects (FAM:SF-CHT-029, FAM:SF-APPS-073).",
  "The significant risk of artifacts arising from derived labels (e.g., play types) if the underlying data construction has leakage or biases (FAM:SF-PAP-096).",
  "The difficulty of making inferences from inferred labels when they cannot reliably distinguish between underlying phenomena (FAM:SF-APPA-005, FAM:SF-CHT-052).",
  "The need for proper matching or placebo controls in studies involving player or lineup effects to avoid misleading results (FAM:SF-CHT-009)."
 ],
 "evidence_does_not_establish": [
  "Specific definitions or methods for identifying 'organizer, shaper, terminal' roles.",
  "Whether these roles can be reliably inferred from play-by-play data without significant label error.",
  "A proven method for separating lineup role effects from raw player talent/counts.",
  "The expected magnitude or direction of the proposed effects.",
  "Whether 'talent control' behaves as expected when applied to these specific roles."
 ],
 "own_inferences": [
  "The 'organizer, shaper, terminal' roles will need to be carefully defined and inferred from play-by-play data, which is a significant methodological challenge given past failures with inferred labels.",
  "Controlling for 'talent/counts' will likely require a robust fixed-effects model (e.g., team-season fixed effects or player fixed effects) to isolate lineup composition effects from individual player quality.",
  "The 'separability' aspect implies a need to demonstrate that the role coverage variables explain variance in outcomes beyond what can be explained by player talent metrics alone."
 ],
 "uncertainties": [
  "The precise definition and operationalization of 'organizer, shaper, terminal' roles from the available play-by-play data.",
  "The reliability and validity of any derived labels for these roles.",
  "The specific methodology for 'talent control' and how its 'behavior' will be assessed.",
  "Whether sufficient within-team variation in lineup coverage exists to power the analysis, after controlling for talent."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence, particularly FAM:SF-APPA-005, FAM:SF-CHT-052, FAM:SF-PAP-096, FAM:SF-CHT-029, and FAM:SF-APPS-073, strongly cautions against proceeding without significant changes. It highlights the critical risks associated with inferred labels, data leakage, and confounding if within-team analysis and robust controls are not meticulously designed. The evidence shifts the decision from a direct 'proceed' to 'proceed_with_changes' and necessitates a detailed design focused on mitigating these known failure mechanisms, especially concerning role definition and talent control."
 },
 "testability": {
  "p_testable": 0.4,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The definition and inference of 'organizer, shaper, terminal' roles from play-by-play data are highly susceptible to label error, which can make the question untestable or lead to artifacts (FAM:SF-APPA-005, FAM:SF-CHT-052)."
   },
   {
    "code": "CONFOUNDING",
    "text": "Separating lineup role effects from player talent/counts is prone to confounding by team quality or other unobserved factors, requiring rigorous within-team controls (FAM:SF-CHT-029, FAM:SF-APPS-073)."
   },
   {
    "code": "LEAKAGE_LOOKAHEAD",
    "text": "The process of deriving player roles from play-by-play data could introduce leakage, similar to the assisted flag issue (FAM:SF-PAP-096), creating spurious effects."
   }
  ]
 },
 "prior_work": {
  "already_answered": "no",
  "cited": [],
  "summary": "No prior work directly addresses the specific research question of lineup coverage by organizer, shaper, terminal roles, its separability from talent, and the behavior of talent control within teams. However, several studies highlight critical methodological challenges related to inferred labels, confounding, and artifact generation that are highly relevant to this question."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The 'organizer, shaper, terminal' roles are derived labels from play-by-play data. Errors or ambiguities in their definition and inference can lead to unreliable measures, making it difficult to test the hypothesis (FAM:SF-APPA-005, FAM:SF-CHT-052)."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player talent, team quality, and opponent strength are major confounders. Without robust controls (e.g., within-team fixed effects), any observed effects of role coverage could be attributed to these factors (FAM:SF-CHT-029, FAM:SF-APPS-073)."
  },
  {
   "code": "LEAKAGE_LOOKAHEAD",
   "text": "The derivation of player roles from play-by-play data must be free of any information that would not be available at the time of the decision or contain inherent biases (e.g., using outcomes to define roles that are meant to predict outcomes) (FAM:SF-PAP-096)."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "While 420,993 possessions and 90 team-seasons are available, specific lineup combinations with particular role coverages might have sparse observations, especially within-team, leading to insufficient power for detecting effects or reliably estimating parameters."
  },
  {
   "code": "PLACEBO_DEPENDENCE",
   "text": "Without proper placebo tests or matched baselines, it's hard to distinguish true effects from statistical artifacts or baseline variations (FAM:SF-CHT-009)."
  }
 ],
 "predicted_outcome": {
  "supported": 0.1,
  "rejected": 0.2,
  "untestable": 0.4,
  "artifact": 0.2,
  "uncertain": 0.1
 },
 "decision": "proceed_with_changes",
 "design": {
  "estimand": "The causal effect of specific lineup role coverage combinations (e.g., >=1 organizer, shaper, terminal) on offensive efficiency (PPP) within a team, controlling for individual player talent and opponent defense. Specifically, we estimate the marginal effect of adding an 'organizer', 'shaper', or 'terminal' to a lineup, holding other roles and talent constant.",
  "unit": "Possession-level observation, aggregated to lineup-by-opponent-by-game-half or lineup-by-team-season for analysis.",
  "sample": "NBA 2022-23 through 2025-26 regular season and playoffs. Filter for possessions where offensive and defensive lineups are fully known. Minimum threshold of 'X' possessions per unique lineup combination to be included in analysis, and 'Y' possessions per player for talent estimation.",
  "power": "Target a minimum of 80% power to detect a 0.05 PPP difference at alpha=0.05. A priori power analysis will be conducted after defining role inference and talent control mechanisms, considering the expected variance and minimum effect size of interest. If power is insufficient for granular effects, focus will shift to broader role presence categories.",
  "controls": "1. **Player Role Inference**: Define 'organizer', 'shaper', and 'terminal' roles based on player actions (e.g., initiator, assist, scoring frequency from derived play-type possession records) using a pre-defined rule-based system or supervised learning model trained on expert-labeled data (if available). Validate role labels for consistency and interpretability. 2. **Talent Control**: Implement player fixed effects (e.g., Player Impact Plus-Minus (PIPM) or equivalent) for all 10 players on the court (5 offense, 5 defense). Additionally, use team-season fixed effects to control for overall team quality and coaching schemes, addressing confounding identified in FAM:SF-CHT-029 and FAM:SF-APPS-073. Opponent fixed effects or opponent strength metrics will also be included. 3. **Lineup Coverage**: Create binary indicators for the presence of at least one organizer, shaper, or terminal within a lineup. Interaction terms between these indicators and player talent could be explored to test 'talent control behaves'.",
  "falsification": "1. **Placebo Test**: Shuffle role labels randomly within players or teams and re-run the analysis. The observed effects should disappear. 2. **Sensitivity Analysis**: Test alternative definitions of roles and talent controls to ensure robustness of findings. 3. **Within-Team Baseline**: Ensure that any observed effects are stable under within-team (team-season demeaning) analysis to rule out team-level confounding.",
  "multiplicity": "Adjust p-values for multiple comparisons if testing several specific role combinations or interaction effects, using methods like Benjamini-Hochberg or Bonferroni correction, depending on the number of tests.",
  "decision_rule": "The research question will be considered 'supported' if statistically significant (p < 0.05 after multiplicity adjustment) and substantively meaningful effects of lineup role coverage are found, which are demonstrably separable from player talent/counts, and pass falsification tests. If no such effects are found, or falsification tests fail, the outcome will be 'rejected' or 'artifact' respectively.",
  "data_version": "NBA 2022-23, 2023-24, 2024-25 complete seasons (regular season and playoffs); 2025-26 regular season (complete) and playoffs (complete). Per-game files from NBA stats API, including derived play-type possession records."
 }
}

